// Package ctabb holds every primitive canonical type as a ready-made Go
// value, named by its abbreviation: U64 is `u64`, Sh is `sh` (an array of
// strings), Z64 is `z64`. Schema code uses these instead of parsing a type
// string at run time.
//
// canonicaltypes_abbrevs.out.go is generated by generate.sh from the
// canonicaltypes package; regenerate it after the type system changes
// rather than edit it.
package ctabb
